/**
 * Amphoe for one province, loaded on demand.
 *
 * The subdirectory in the path is load-bearing: Vite will not transform a
 * variable import whose pattern could match its own directory, and an
 * untransformed one resolves in dev and fails in a production build.
 */
export async function loadAmphoe(iso: string) {
  const mod = await import(`./amphoe/${iso}.ts`);
  return mod.AMPHOE;
}
